package com.example.domain.model.i18n

internal object DuaDe2 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Schutz vor jedem Schaden", "Im Namen Allahs, mit dessen Namen nichts auf der Erde und im Himmel schaden kann, und Er ist der Allhörende, der Allwissende.", "Wird morgens und abends je dreimal gesprochen.", "Wer es morgens und abends dreimal spricht, dem schadet nichts."),
        "dua_raditu_billahi" to DuaText("Zufrieden mit Allah als Herrn", "Ich bin zufrieden mit Allah als Herrn, mit dem Islam als Religion und mit Muhammad ﷺ als Propheten.", "Wird morgens und abends dreimal gesprochen.", "Allah hat es sich zur Pflicht gemacht, einen solchen Diener am Jüngsten Tag zufriedenzustellen."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Allah genügt mir)", "Allah genügt mir, es gibt keinen Gott außer Ihm, auf Ihn vertraue ich, und Er ist der Herr des gewaltigen Throns.", "Wird morgens und abends siebenmal gesprochen.", "Ein Koranvers; Allah genügt in den Sorgen dieser Welt und des Jenseits."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("Subhanallahi wa bihamdihi", "Gepriesen sei Allah, und Ihm gebührt das Lob.", "Wird hundertmal am Tag gesprochen.", "Wer es hundertmal am Tag spricht, dem werden die Sünden vergeben, auch wenn sie wie der Schaum des Meeres sind."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Es gibt keinen Gott außer Allah, dem Einzigen, ohne Partner. Ihm gehört die Herrschaft, Ihm gebührt das Lob, und Er hat Macht über alle Dinge.", "Große Belohnung, wenn es hundertmal am Tag gesprochen wird.", "Entspricht der Freilassung von zehn Sklaven, hundert guten Taten, der Tilgung von hundert Sünden und Schutz vor dem Satan bis zum Abend."),
        "dua_leaving_mosque" to DuaText("Beim Verlassen der Moschee", "O Allah, ich bitte Dich um Deine Gnade.", "Wird beim Verlassen der Moschee mit dem linken Fuß gesprochen.", "Bitte um Allahs Gnade und Versorgung beim Verlassen der Moschee."),
        "dua_after_adhan" to DuaText("Nach dem Adhan", "O Allah, Herr dieses vollkommenen Rufes und des bevorstehenden Gebets, gib Muhammad ﷺ die Fürsprache und die Vorzüglichkeit, und erhebe ihn zu dem gepriesenen Stand, den Du ihm versprochen hast.", "Wird nach Beendigung des Adhan gesprochen.", "Wer dies spricht, dem wird die Fürsprache des Propheten ﷺ am Tag der Auferstehung zuteil."),
        "dua_after_salah_istighfar" to DuaText("Nach dem Pflichtgebet", "Ich bitte Allah um Vergebung (3-mal). O Allah, Du bist der Friede, und von Dir kommt der Friede; gesegnet bist Du, o Herr der Majestät und Ehre.", "Wird sofort nach dem Friedensgruß gesprochen.", "Der Prophet ﷺ sprach dies nach jedem Pflichtgebet."),
        "dua_after_salah_help_dhikr" to DuaText("Hilf mir, Deiner zu gedenken", "O Allah, hilf mir, Deiner zu gedenken, Dir zu danken und Dir auf die beste Weise zu dienen.", "Nach jedem Gebet — der Prophet ﷺ trug es Muadh (r.a.) auf.", "Besonderer Auftrag des Propheten ﷺ — für Beständigkeit und Güte im Gottesdienst."),
        "dua_sleep_tasbeeh" to DuaText("Tasbih der Fatima vor dem Schlafen", "Subhanallah (33-mal), Alhamdulillah (33-mal), Allahu akbar (34-mal).", "Wird vor dem Schlafen gesprochen — der Prophet ﷺ lehrte es Fatima und Ali (r.a.).", "Der Prophet ﷺ sagte, dies sei besser als ein Diener."),
        "dua_sleep_qina_adhab" to DuaText("Schutz vor der Strafe", "O Allah, bewahre mich vor Deiner Strafe an dem Tag, an dem Du Deine Diener auferweckst.", "Wird dreimal gesprochen, mit der rechten Hand unter der Wange.", "Erinnert im Schlaf an den Tod und die Vorbereitung auf das Jenseits."),
        "dua_bad_dream" to DuaText("Bei einem schlechten Traum", "Ich suche Zuflucht bei Allah vor dem verfluchten Satan.", "Bei einem schlechten Traum: dreimal leicht auf die linke Seite blasen und die Seite wechseln.", "Der schlechte Traum wird nicht schaden; man soll ihn niemandem erzählen."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("O Lebendiger, o Beständiger", "O Lebendiger, o Beständiger, durch Deine Barmherzigkeit rufe ich um Hilfe.", "Wenn eine Angelegenheit sehr schwer wird.", "Der Prophet ﷺ sprach dies, wenn ihn eine Sache bedrückte."),
        "dua_entering_market" to DuaText("Beim Betreten des Marktes", "Es gibt keinen Gott außer Allah, dem Einzigen, ohne Partner. Ihm gehört die Herrschaft, Ihm gebührt das Lob. Er macht lebendig und lässt sterben, und Er ist lebendig und stirbt nicht. In Seiner Hand liegt alles Gute, und Er hat Macht über alle Dinge.", "Wird beim Betreten des Marktes gesprochen.", "In der Überlieferung wird eine sehr große Belohnung dafür genannt (Millionen guter Taten)."),
        "dua_adam_forgiveness" to DuaText("Das Bittgebet Adams", "Unser Herr, wir haben uns selbst Unrecht getan, und wenn Du uns nicht vergibst und Dich unser nicht erbarmst, gehören wir sicher zu den Verlierern.", "Das Reuegebet Adams und Hawwas (Friede sei mit ihnen).", "Die erste Reue der Menschheit — Allah nahm sie an."),
        "dua_abu_bakr" to DuaText("Das Bittgebet für Abu Bakr", "O Allah, ich habe mir selbst großes Unrecht getan, und niemand vergibt Sünden außer Dir; so vergib mir aus Deiner Gnade und erbarme Dich meiner, wahrlich, Du bist der Vergebende, der Barmherzige.", "Der Prophet ﷺ lehrte es Abu Bakr (r.a.) zum Sprechen im Gebet (nach dem Tashahhud).", "Sunna-Bittgebet am Ende des Gebets."),
        "dua_astaghfirullah_atubu" to DuaText("Tägliches Istighfar", "Ich bitte Allah um Vergebung und wende mich Ihm reuevoll zu.", "Der Prophet ﷺ bat mehr als siebzigmal am Tag um Vergebung.", "Der Prophet ﷺ sagte: Ich bitte Allah täglich mehr als siebzigmal um Vergebung und wende mich Ihm zu."),
        "dua_laylatul_qadr" to DuaText("Bittgebet für die Nacht der Bestimmung", "O Allah, Du bist der Verzeihende und liebst das Verzeihen, so verzeihe mir.", "Der Prophet ﷺ lehrte es Aischa (r.a.) für die Nacht der Bestimmung.", "Besonderes Bittgebet für die letzten Nächte des Ramadan und Laylatul Qadr."),
        "dua_family_coolness" to DuaText("Die Augenweide von Frau und Kindern", "Unser Herr, schenke uns durch unsere Frauen und Nachkommen Augenweide und mache uns zu Vorbildern für die Gottesfürchtigen.", "Koranisches Bittgebet für eine rechtschaffene Familie.", "Für Ruhe im Haus und rechtschaffene Nachkommen."),
        "dua_righteous_children" to DuaText("Für rechtschaffene Nachkommen", "Mein Herr, schenke mir von Dir aus gute Nachkommenschaft; wahrlich, Du bist der Erhörer des Gebets.", "Das Bittgebet des Propheten Zakariya (Friede sei mit ihm).", "Koranisches Bittgebet um Nachkommen."),
        "dua_ibrahim_prayer_family" to DuaText("Die das Gebet verrichten", "Mein Herr, mache mich und meine Nachkommen zu denen, die das Gebet verrichten. Unser Herr, nimm mein Bittgebet an. Unser Herr, vergib mir, meinen Eltern und den Gläubigen am Tag der Abrechnung.", "Das Bittgebet Ibrahims (Friede sei mit ihm) für sich und seine Nachkommen.", "Wird häufig am Ende des Gebets gesprochen."),
        "dua_newlywed" to DuaText("Glückwunsch für Brautpaar", "Möge Allah dich segnen, dir Segen herabsenden und euch beide im Guten vereinen.", "Wird demjenigen gesagt, der geheiratet hat.", "Sunna-Glückwunsch zur Hochzeit."),
        "dua_before_eating" to DuaText("Vor dem Essen", "Im Namen Allahs. (Wenn vergessen:) Im Namen Allahs am Anfang und am Ende.", "Vor dem Essen; wird es vergessen, spricht man es in der Mitte.", "Durch das Sprechen von Bismillah nimmt der Satan nicht am Essen teil."),
        "dua_after_eating" to DuaText("Nach dem Essen", "Alles Lob gebührt Allah, der mich gespeist hat und mir dies ohne meine Kraft und Macht als Versorgung gegeben hat.", "Wird nach Beendigung des Essens gesprochen.", "Wer es spricht, dem werden die vergangenen Sünden vergeben."),
        "dua_host" to DuaText("Für den Gastgeber", "O Allah, segne, was Du ihnen an Versorgung gegeben hast, vergib ihnen und erbarme Dich ihrer.", "Für den Gastgeber, nachdem man bei jemandem gegessen hat.", "Sunna-Dank an den Gastgeber."),
        "dua_breaking_fast" to DuaText("Beim Fastenbrechen", "Der Durst ist gewichen, die Adern sind feucht geworden, und die Belohnung ist, so Allah will, gesichert.", "Wird beim Fastenbrechen (Iftar) gesprochen.", "Der Prophet ﷺ sagte dies beim Fastenbrechen."),
        "dua_new_clothes" to DuaText("Neue Kleidung anziehen", "O Allah, Dir gebührt das Lob; Du hast mich dies gekleidet. Ich bitte Dich um sein Gutes und das Gute, wofür es gemacht wurde, und ich suche Zuflucht bei Dir vor seinem Übel und dem Übel, wofür es gemacht wurde.", "Beim Anziehen neuer Kleidung, wobei man den Namen des Kleidungsstücks nennt.", "Der Prophet ﷺ sprach dies beim Anziehen neuer Kleidung."),
        "dua_rabbana_atina" to DuaText("Das Gute in dieser und jener Welt", "Unser Herr, gib uns Gutes in dieser Welt und Gutes im Jenseits, und bewahre uns vor der Strafe des Feuers.", "Das meistgesprochene Bittgebet des Propheten ﷺ.", "Ein Bittgebet, das jedes Gute in dieser und der nächsten Welt umfasst."),
        "dua_rabbi_zidni_ilma" to DuaText("Mehrung des Wissens", "Mein Herr, mehre mein Wissen.", "Für die Mehrung des Wissens.", "Allah befahl dem Propheten ﷺ, nur um mehr Wissen zu bitten."),
        "dua_musa_sharh_sadr" to DuaText("Öffnung der Brust (Musa)", "Mein Herr, weite mir meine Brust, erleichtere mir meine Aufgabe und löse den Knoten von meiner Zunge, damit die Menschen meine Rede verstehen.", "Vor einer Prüfung, einer Rede oder einer schwierigen Aufgabe.", "Das Bittgebet Musas (Friede sei mit ihm) — für Herzensruhe und Erleichterung."),
        "dua_la_tuzigh" to DuaText("Beständigkeit des Herzens", "Unser Herr, lass unsere Herzen nicht abweichen, nachdem Du uns rechtgeleitet hast, und schenke uns Barmherzigkeit von Dir; wahrlich, Du bist der Gebende.", "Für Standhaftigkeit auf der Rechtleitung.", "Bittgebet um Standhaftigkeit im Glauben."),
        "dua_ya_muqallib" to DuaText("O Wender der Herzen", "O Wender der Herzen, festige mein Herz auf Deiner Religion.", "Der Prophet ﷺ sprach dieses Bittgebet oft.", "Nach Umm Salama (r.a.) das meistgesprochene Bittgebet des Propheten ﷺ."),
        "dua_la_tuakhidhna" to DuaText("Die letzten Verse von Surat al-Baqara", "Unser Herr, stelle uns nicht zur Rechenschaft, wenn wir vergessen oder einen Fehler machen. Unser Herr, lege uns keine Last auf, wie Du sie denen vor uns auferlegt hast. Unser Herr, lade uns nicht auf, was wir nicht tragen können. Vergib uns, verzeihe uns und erbarme Dich unser. Du bist unser Beschützer, so hilf uns gegen das ungläubige Volk.", "Wird nachts vor dem Schlafen gesprochen — die letzten beiden Verse von Surat al-Baqara.", "Wer sie nachts spricht, dem genügen sie."),
        "dua_visiting_sick" to DuaText("Krankenbesuch", "Ich bitte den gewaltigen Allah, den Herrn des gewaltigen Throns, dass Er dich heilt.", "Wird beim Krankenbesuch siebenmal gesprochen.", "Wenn die Todesstunde noch nicht gekommen ist, heilt Allah ihn."),
        "dua_ruqyah_pain" to DuaText("Bei Körperschmerz", "Ich suche Zuflucht bei Allah und Seiner Macht vor dem Übel dessen, was ich empfinde und fürchte.", "Hand auf den Schmerz legen, dreimal Bismillah, dann siebenmal dieses Bittgebet.", "Der Prophet ﷺ lehrte es Uthman ibn Abi al-As (r.a.) gegen Schmerz."),
        "dua_ruqyah_nabawi" to DuaText("Prophetische Heilbitte für Kranke", "O Allah, Herr der Menschen, nimm die Not, heile, Du bist der Heiler, es gibt keine Heilung außer Deiner Heilung, eine Heilung, die keine Krankheit zurücklässt.", "Wird gesprochen, während man mit der Hand über den Kranken streicht.", "Der Prophet ﷺ sprach dies beim Besuch seiner Angehörigen."),
        "dua_kalimat_tammat" to DuaText("Zuflucht in den vollkommenen Worten", "Ich suche Zuflucht in den vollkommenen Worten Allahs vor dem Übel dessen, was Er erschaffen hat.", "Beim Rasten an einem Ort oder abends.", "Wer dies an einem Ort spricht, dem schadet nichts, bis er ihn verlässt."),
        "dua_evil_eye" to DuaText("Schutz der Kinder (böser Blick)", "Ich vertraue euch beide den vollkommenen Worten Allahs an, vor jedem Satan und Ungeziefer und vor jedem schädlichen Blick.", "Der Prophet ﷺ sprach dies über Hasan und Husain (r.a.).", "Sunna-Schutzgebet für Kinder vor bösem Blick und Übel."),
        "dua_seeing_afflicted" to DuaText("Beim Anblick eines Betroffenen", "Alles Lob gebührt Allah, der mich vor dem bewahrt hat, womit Er dich geprüft hat, und mich vor vielen Seiner Geschöpfe bevorzugt hat.", "Beim Anblick eines Betroffenen (im Stillen sprechen).", "Wer es spricht, bleibt vor jenem Unglück bewahrt."),
        "dua_istikhara" to DuaText("Das Bittgebet der Istikhara", "O Allah, ich bitte Dich durch Dein Wissen um das Gute, ich bitte Dich durch Deine Macht um Kraft, und ich bitte Dich um Deine gewaltige Gnade. Du hast Macht, ich habe keine Macht, Du weißt, ich weiß nicht, und Du bist der Kenner des Verborgenen. O Allah, wenn Du weißt, dass diese Angelegenheit gut für mich ist in meiner Religion, meinem Leben und meinem Ende, so bestimme sie für mich, erleichtere sie mir und segne sie mir. Und wenn Du weißt, dass diese Angelegenheit schlecht für mich ist, so wende sie von mir ab und mich von ihr, und bestimme mir das Gute, wo immer es sei, und lass mich damit zufrieden sein.", "Nach zwei freiwilligen Rakat, um in einer erlaubten Angelegenheit um das Gute zu bitten.", "Der Prophet ﷺ lehrte den Gefährten die Istikhara wie eine Sure des Korans."),
        "dua_allahumma_bika_asbahna" to DuaText("Allahumma bika asbahna", "O Allah, durch Dich haben wir den Morgen erreicht, und durch Dich haben wir den Abend erreicht; durch Dich leben wir und sterben wir, und zu Dir ist die Auferstehung.", "Wird morgens gesprochen.", "Der Prophet ﷺ lehrte dies den Gefährten für morgens und abends."),
        "dua_allahumma_bika_amsayna" to DuaText("Allahumma bika amsayna", "O Allah, durch Dich haben wir den Abend erreicht, und durch Dich haben wir den Morgen erreicht; durch Dich leben wir und sterben wir, und zu Dir ist die Rückkehr.", "Wird abends gesprochen.", "Der Prophet ﷺ lehrte dies den Gefährten für morgens und abends."),
        "dua_afiyah_morning" to DuaText("Bittgebet um Wohlergehen", "O Allah, ich bitte Dich um Verzeihung und Wohlergehen in dieser und der nächsten Welt.", "Der Prophet ﷺ ließ dieses Bittgebet morgens und abends nie aus.", "Nichts Besseres als Wohlergehen wurde jemandem gegeben."),
        "dua_afini_fi_badani" to DuaText("Wohlergehen für Körper, Gehör und Sehkraft", "O Allah, gib mir Wohlergehen in meinem Körper, gib mir Wohlergehen in meinem Gehör, gib mir Wohlergehen in meinem Augenlicht. Es gibt keinen Gott außer Dir.", "Wird morgens und abends je dreimal gesprochen.", "Bittgebet um Gesundheit und den Schutz der Sinne."),
        "dua_ya_hayyu_aslih" to DuaText("Ordne all meine Angelegenheiten", "O Lebendiger, o Beständiger, durch Deine Barmherzigkeit rufe ich um Hilfe. Ordne all meine Angelegenheiten und überlasse mich nicht meinem Selbst, auch nicht für einen Augenblick.", "Der Prophet ﷺ trug Fatima (r.a.) auf, es morgens und abends zu sprechen.", "Bitte um Allahs Hilfe in allen Angelegenheiten."),
        "dua_subhanallah_adada_khalqihi" to DuaText("Der Tasbih von Juwayriya", "Gepriesen sei Allah, und Ihm gebührt das Lob — so viel wie die Zahl Seiner Geschöpfe, nach Seinem Wohlgefallen, so schwer wie Sein Thron und so viel wie die Tinte Seiner Worte.", "Dreimal morgens gesprochen — schwerer als stundenlanges Gedenken.", "Diese vier Worte, dreimal gesprochen, wiegen schwerer als das Gedenken vom Morgen bis zum Mittag."),
        "dua_salawat" to DuaText("Der ibrahimitische Segensgruß", "O Allah, segne Muhammad ﷺ und die Familie Muhammads, wie Du Ibrahim und die Familie Ibrahims gesegnet hast; wahrlich, Du bist des Lobes würdig, des Ruhmes würdig. O Allah, segne mit Segen Muhammad ﷺ und die Familie Muhammads, wie Du Ibrahim und die Familie Ibrahims gesegnet hast; wahrlich, Du bist des Lobes würdig, des Ruhmes würdig.", "Im Gebet und jederzeit als Segensgruß für den Propheten ﷺ.", "Wer einmal den Segensgruß spricht, dem sendet Allah zehnfachen Segen (Muslim 408)."),
        "dua_wudu_after" to DuaText("Nach der Gebetswaschung", "Ich bezeuge, dass es keinen Gott außer Allah gibt, dem Einzigen, ohne Partner, und dass Muhammad ﷺ Sein Diener und Gesandter ist. O Allah, mache mich zu den Reuigen und mache mich zu den Reinen.", "Nach Vollendung der Gebetswaschung.", "Alle acht Tore des Paradieses werden geöffnet, durch welches er will, tritt er ein."),
        "dua_wudu_before" to DuaText("Vor der Gebetswaschung", "Im Namen Allahs.", "Zu Beginn der Gebetswaschung.", "Wer bei der Gebetswaschung nicht den Namen Allahs erwähnt, dessen Waschung ist nicht vollkommen."),
        "dua_istiftah" to DuaText("Das Eröffnungsbittgebet des Gebets", "O Allah, gepriesen seist Du, und Dir gebührt das Lob, gesegnet ist Dein Name, erhaben ist Deine Herrlichkeit, und es gibt keinen Gott außer Dir.", "Zu Beginn des Gebets, sofort nach dem Eröffnungstakbir.", "Sunna-Eröffnungsgebet."),
        "dua_ruku" to DuaText("In der Verbeugung", "Gepriesen sei mein Herr, der Gewaltige.", "Mindestens dreimal in der Verbeugung.", "Sunna-Lobpreisung in der Verbeugung."),
        "dua_sujood" to DuaText("In der Niederwerfung", "Gepriesen sei mein Herr, der Höchste.", "Mindestens dreimal in der Niederwerfung.", "Der Diener ist seinem Herrn in der Niederwerfung am nächsten (Muslim 482)."),
        "dua_rising_ruku" to DuaText("Beim Aufrichten aus der Verbeugung", "Allah erhört den, der Ihn lobt. Unser Herr, Dir gebührt alles Lob.", "Beim Aufrichten aus der Verbeugung und beim geraden Stehen.", "Wessen Lobpreisung mit der der Engel zusammentrifft, dem werden die vergangenen Sünden vergeben."),
        "dua_between_sajdas" to DuaText("Zwischen den zwei Niederwerfungen", "Mein Herr, vergib mir, mein Herr, vergib mir.", "Beim Sitzen zwischen den beiden Niederwerfungen.", "Sunna-Bittgebet beim Sitzen."),
        "dua_before_salam_four" to DuaText("Schutz vor vier Dingen (vor dem Friedensgruß)", "O Allah, ich suche Zuflucht bei Dir vor der Strafe der Hölle, vor der Strafe des Grabes, vor der Versuchung des Lebens und des Todes, und vor dem Übel der Versuchung des Dajjal.", "Nach dem letzten Tashahhud und dem Segensgruß, vor dem Friedensgruß.", "Der Prophet ﷺ befahl, vor diesen vier Dingen Zuflucht zu suchen."),
        "dua_qunoot_witr" to DuaText("Qunut im Witr-Gebet", "O Allah, leite mich unter denen, die Du rechtgeleitet hast, gib mir Wohlergehen unter denen, denen Du Wohlergehen gegeben hast, nimm mich in Deine Obhut unter denen, die Du beschützt hast, segne mir, was Du mir gegeben hast, und bewahre mich vor dem Übel dessen, was Du bestimmt hast. Wahrlich, Du bestimmst, und über Dich wird nicht bestimmt, und wer Dein Freund ist, wird nicht erniedrigt. Unser Herr, gesegnet und erhaben bist Du.", "Im Witr-Gebet — der Prophet ﷺ lehrte es Hasan ibn Ali (r.a.).", "Sunna-Qunut des Witr-Gebets."),
        "dua_qunoot_hanafi" to DuaText("Qunut (Allahumma inna nastainuka)", "O Allah, wir bitten Dich um Hilfe und Vergebung, wir glauben an Dich und vertrauen auf Dich, wir loben Dich in bestem Maße, wir danken Dir und sind nicht undankbar, und wir verlassen und meiden, wer Dir ungehorsam ist. O Allah, Dir allein dienen wir, für Dich beten wir und werfen uns nieder, zu Dir eilen und streben wir, wir hoffen auf Deine Barmherzigkeit und fürchten Deine Strafe; wahrlich, Deine Strafe wird die Ungläubigen erreichen.", "Im Witr-Gebet — die Praxis der Hanafiten.", "Von Umar (r.a.) im Qunut überliefert."),
        "dua_sleep_aslamtu" to DuaText("Letzte Worte vor dem Schlafen", "O Allah, ich habe meine Seele Dir übergeben, meine Angelegenheit Dir anvertraut, meinen Rücken Dir zugewandt, aus Verlangen und Furcht vor Dir. Es gibt keine Zuflucht und keine Rettung vor Dir außer zu Dir. Ich glaube an Dein herabgesandtes Buch und an Deinen gesandten Propheten.", "Nach der Waschung, auf der rechten Seite liegend — als letzte Worte.", "Stirbt man in dieser Nacht, stirbt man auf der Fitra (dem Islam)."),
        "dua_waking_night" to DuaText("Beim nächtlichen Erwachen", "Es gibt keinen Gott außer Allah, dem Einzigen, ohne Partner; Ihm gehört die Herrschaft und Ihm gebührt das Lob, und Er hat Macht über alle Dinge. Alles Lob gebührt Allah, gepriesen sei Allah, es gibt keinen Gott außer Allah, Allah ist am größten, und es gibt keine Kraft und keine Macht außer durch Allah. O Allah, vergib mir.", "Beim nächtlichen Erwachen.", "Das Bittgebet wird erhört, und wenn er die Waschung vollzieht und betet, wird sein Gebet angenommen."),
        "dua_hamm_ibn_masud" to DuaText("Bittgebet gegen Kummer (Ibn Masud)", "O Allah, ich bin Dein Diener, Sohn Deines Dieners, Sohn Deiner Dienerin. Meine Stirn liegt in Deiner Hand, Dein Urteil über mich ist ausgeführt, Deine Bestimmung über mich ist gerecht. Ich bitte Dich bei jedem Namen, mit dem Du Dich selbst benannt hast, oder den Du in Deinem Buch herabgesandt hast, oder den Du einem Deiner Geschöpfe gelehrt hast, oder den Du bei Dir im Verborgenen bewahrt hast — mache den Koran zum Frühling meines Herzens, zum Licht meiner Brust, zur Heilung meines Kummers und zur Vertreibung meiner Sorge.", "Bei Kummer und Sorge — Allah verwandelt den Kummer in Freude.", "Allah vertreibt Sorge und Kummer und schenkt Freude dafür."),
        "dua_difficulty_sahl" to DuaText("Wenn etwas schwer fällt", "O Allah, nichts ist leicht außer dem, was Du leicht machst, und Du machst die Schwierigkeit leicht, wenn Du willst.", "Wenn eine Angelegenheit schwierig erscheint.", "Erleichterung bei Prüfungen und schwierigen Aufgaben."),
        "dua_musibah" to DuaText("Beim Unglück (Istirja)", "Wir gehören Allah, und zu Ihm kehren wir zurück. O Allah, belohne mich für mein Unglück und ersetze mir Besseres dafür.", "Bei jedem Verlust oder Unglück.", "Allah gibt gewiss einen besseren Ersatz — so geschah es Umm Salama (r.a.)."),
        "dua_debt" to DuaText("Befreiung von Schulden", "O Allah, genüge mir durch Dein Erlaubtes anstelle Deines Verbotenen, und mache mich durch Deine Gnade unabhängig von allen außer Dir.", "Zur Tilgung von Schulden — gelehrt von Ali (r.a.).", "Auch wenn die Schuld so groß wie ein Berg wäre, würde Allah sie begleichen lassen."),
        "dua_anger" to DuaText("Bei Zorn", "Ich suche Zuflucht bei Allah vor dem verfluchten Satan.", "Wenn Zorn aufkommt.", "Der Prophet ﷺ sagte: Spricht er dies, vergeht sein Zorn."),
        "dua_waswasa" to DuaText("Gegen Einflüsterungen im Glauben", "Ich glaube an Allah und Seine Gesandten.", "Wenn teuflische Einflüsterungen über den Glauben aufkommen.", "Bei Einflüsterungen dies sprechen und innehalten (auch Zuflucht bei Allah suchen)."),
        "dua_travel_full" to DuaText("Das vollständige Reisegebet", "O Allah, wir bitten Dich auf dieser Reise um Rechtschaffenheit, Gottesfurcht und Taten, die Dir gefallen. O Allah, erleichtere uns diese Reise und verkürze uns ihre Weite. O Allah, Du bist der Gefährte auf der Reise und der Beschützer der Familie.", "Beim Aufbruch zur Reise, nach dem Ausspruch 'Subhanalladhi sakhkhara'.", "Vollständiges Sunna-Reisegebet."),
        "dua_return_travel" to DuaText("Rückkehr von der Reise", "Wir kehren zurück, bereuen, dienen und loben unseren Herrn.", "Bei der Rückkehr von einer Reise.", "Der Prophet ﷺ sprach dies bei der Rückkehr von einer Reise."),
        "dua_farewell_traveller" to DuaText("Abschied vom Reisenden", "Ich vertraue Allah deine Religion, deine Treue und das Ende deiner Taten an.", "Beim Verabschieden eines Reisenden.", "Was Allah anvertraut wird, geht nicht verloren."),
        "dua_entering_town" to DuaText("Beim Rasten an einem Ort", "Ich suche Zuflucht in den vollkommenen Worten Allahs vor dem Übel jeder Schöpfung.", "Beim Rasten an einem Ort oder Ankommen in einer neuen Stadt.", "Nichts wird ihm bis zum Aufbruch von dort schaden."),
        "dua_boarding_ship" to DuaText("Beim Besteigen eines Schiffes", "Im Namen Allahs ist seine Fahrt und sein Anlegen; wahrlich, mein Herr ist voller Vergebung und Barmherzigkeit.", "Beim Besteigen eines Schiffes oder Fahrzeugs — der Ausspruch Nuhs (Friede sei mit ihm).", "Koranvers — das Bittgebet Nuhs für sein Schiff."),
        "dua_istighfar_hayyul_qayyum" to DuaText("Istighfar mit Hayyul Qayyum", "Ich bitte um Vergebung bei Allah, außer dem es keinen Gott gibt, dem Lebendigen, dem Beständigen, und ich wende mich Ihm reuevoll zu.", "Für die Reue.", "Die Sünden werden vergeben, auch wenn man vom Schlachtfeld geflohen ist."),
        "dua_rabbighfir_warham" to DuaText("Rabbighfir warham", "Mein Herr, vergib und erbarme Dich, und Du bist der Beste der Barmherzigen.", "Koranisches Bittgebet um Vergebung und Barmherzigkeit.", "Der letzte Vers von Surat al-Muminun."),
        "dua_majlis_kaffarah" to DuaText("Sühne für die Versammlung", "Gepriesen seist Du, o Allah, und Dir gebührt das Lob. Ich bezeuge, dass es keinen Gott außer Dir gibt. Ich bitte Dich um Vergebung und wende mich Dir reuevoll zu.", "Beim Verlassen einer Versammlung.", "Wird zur Sühne für Fehler, die in der Versammlung geschahen."),
        "dua_jami_forgiveness" to DuaText("Umfassendes Vergebungsgebet", "O Allah, vergib mir meinen Fehler, meine Unwissenheit, mein Übermaß in meinen Angelegenheiten und was Du besser weißt als ich.", "Das umfassende Bittgebet des Propheten ﷺ.", "Der Prophet ﷺ pflegte dies zu bitten."),
        "dua_parents_nuh" to DuaText("Bittgebet Nuhs für die Eltern", "Mein Herr, vergib mir, meinen Eltern, jedem, der als Gläubiger mein Haus betritt, und allen gläubigen Männern und Frauen.", "Für die Eltern und die Gläubigen.", "Das Bittgebet des Propheten Nuh (Friede sei mit ihm)."),
        "dua_shukr_parents" to DuaText("Dank für die Eltern und rechtschaffene Nachkommen", "Mein Herr, gib mir ein, für Deine Gnade zu danken, die Du mir und meinen Eltern erwiesen hast, und Gutes zu tun, das Dir gefällt, und mach mir auch meine Nachkommen rechtschaffen. Ich wende mich Dir reuevoll zu, und ich gehöre zu den Ergebenen.", "Koranisches Bittgebet für das Alter von vierzig Jahren.", "Dank, gute Taten und die Besserung der Nachkommen — alles in einem Bittgebet."),
        "dua_intimacy" to DuaText("Vor der ehelichen Vereinigung", "Im Namen Allahs. O Allah, halte den Satan von uns fern, und halte den Satan fern von dem, was Du uns schenkst.", "Vor der ehelichen Vereinigung.", "Wird ein Kind bestimmt, wird der Satan ihm niemals schaden."),
        "dua_ibrahim_children_protection" to DuaText("Schutz von Heimat und Nachkommen", "Mein Herr, mache diese Stadt sicher, und bewahre mich und meine Nachkommen davor, Götzen zu dienen.", "Das Bittgebet Ibrahims (Friede sei mit ihm) für Stadt und Nachkommen.", "Bittgebet um Standhaftigkeit im reinen Glauben."),
        "dua_drinking_milk" to DuaText("Beim Trinken von Milch", "O Allah, segne uns darin und gib uns noch mehr davon.", "Beim Trinken von Milch.", "Nichts genügt sowohl als Speise als auch als Getränk außer Milch."),
        "dua_iftar_host" to DuaText("Beim Fastenbrechen als Gast", "Möge bei euch Fastende das Fasten brechen, mögen Rechtschaffene von eurem Essen essen, und mögen die Engel für euch beten.", "Beim Fastenbrechen bei jemandem als Gast.", "Das Dankgebet des Propheten ﷺ für den Gastgeber."),
        "dua_seeing_first_fruit" to DuaText("Beim Anblick der ersten Frucht", "O Allah, segne uns in unseren Früchten, in unserer Stadt, in unserem Sa und unserem Mudd.", "Beim Anblick der ersten Frucht der Saison.", "Bittgebet um Segen für Versorgung und Stadt."),
        "dua_good_news" to DuaText("Bei guter Nachricht", "Alles Lob gebührt Allah, durch dessen Gnade gute Taten vollendet werden.", "Bei einer freudigen Nachricht (und Niederwerfung des Dankes).", "Der Prophet ﷺ sagte dies beim Anblick von etwas Erfreulichem."),
        "dua_looking_mirror" to DuaText("Beim Blick in den Spiegel", "O Allah, wie Du mein Äußeres schön gemacht hast, so mache auch meinen Charakter schön.", "Beim Blick in den Spiegel.", "Der Prophet ﷺ sprach dieses Bittgebet (auch ohne Spiegel überliefert)."),
        "dua_rabbana_taqabbal" to DuaText("Annahme der Taten", "Unser Herr, nimm von uns an, wahrlich, Du bist der Allhörende, der Allwissende. Und nimm unsere Reue an, wahrlich, Du bist der Reue-Annehmende, der Barmherzige.", "Von Ibrahim und Ismail (Friede sei mit ihnen) beim Bau der Kaaba gesprochen.", "Bittgebet um Annahme nach jeder guten Tat."),
    )
}
